    sess = saved
    if sess is not None:
        try:
            listing = _call(transport, "GET", f"{BASE}/uploads/{sess.upload_id}/parts")
        except ApiError as e:
            if (e.status, e.code) not in ((410, "upload_expired"), (404, "not_found")):
                raise
